/* Hunter System – local-first standalone PWA. No third-party runtime dependencies. */
(() => {
  'use strict';
  const KEY = 'hunter-system-data-v1';
  const icons = {
    home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
    dumbbell:'<path d="m6.5 6.5 11 11m-15-8 7-7m5 19 7-7M3 6l3-3m12 18 3-3M5 12 12 5m7 14-7-7"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
    scroll:'<path d="M8 21h10a3 3 0 0 0 3-3V5a2 2 0 0 0-2-2H6a3 3 0 0 0-3 3v12a3 3 0 0 0 3 3zM6 17v1a3 3 0 0 0 3 3M8 8h9M8 12h8"/>',
    chart:'<path d="M3 3v18h18M7 16l4-5 4 2 5-7"/>',
    gear:'<path d="M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7z"/><path d="m19 13 .2-2 2-1-2-3-2 1-1.8-1.2V4h-4v2.8L9.5 8 7.5 7l-2 3 2 1-.1 2-2 1 2 3 2-1 1.9 1.2V20h4v-2.8l1.8-1.2 2 1 2-3z"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    chevron:'<path d="m9 18 6-6-6-6"/>',
    back:'<path d="m15 18-6-6 6-6"/>',
    arrowup:'<path d="m12 19 0-14m-6 6 6-6 6 6"/>',
    arrowdown:'<path d="m12 5 0 14m-6-6 6 6 6-6"/>',
    trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/>',
    edit:'<path d="m16 4 4 4-12 12H4v-4L16 4ZM14 6l4 4"/>',
    moon:'<path d="M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z"/>',
    zap:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',
    timer:'<circle cx="12" cy="13" r="9"/><path d="M12 13V8m-3-6h6"/>',
    star:'<path d="m12 3 2.8 5.6 6.2.9-4.5 4.4 1 6.1-5.5-2.9-5.5 2.9 1-6.1L3 9.5l6.2-.9Z"/>',
    download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
    upload:'<path d="M12 21V8m-5 5 5-5 5 5M4 7V3h16v4"/>',
    cloud:'<path d="M7 18h11a4 4 0 0 0 0-8 6 6 0 0 0-11.4-1.7A5 5 0 0 0 7 18Z"/>',
    refresh:'<path d="M20 11a8 8 0 0 0-14-5L3 9m0-6v6h6M4 13a8 8 0 0 0 14 5l3-3m0 6v-6h-6"/>',
    x:'<path d="M18 6 6 18M6 6l12 12"/>',
    alert:'<path d="m12 2 10 19H2L12 2ZM12 9v5m0 3h.01"/>',
    heart:'<path d="M20.8 8.5c0 5.1-8.8 11-8.8 11S3.2 13.6 3.2 8.5a4.7 4.7 0 0 1 8.8-2.2 4.7 4.7 0 0 1 8.8 2.2Z"/>',
    crown:'<path d="m2 7 5 5 5-8 5 8 5-5-2 12H4Z"/>',
    shield:'<path d="M12 2 4 6v6c0 5 3 8 8 10 5-2 8-5 8-10V6Z"/>',
    play:'<path d="m8 5 12 7-12 7z"/>',
    external:'<path d="M14 4h6v6m0-6-10 10M20 14v6H4V4h6"/>',
    info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',
    menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',
    run:'<path d="m13 4 2 3-4 4 3 2 4 6M8 21l4-5-3-2-3 4m4-15h.01"/>',
    edit2:'<path d="M12 20h9M16 4l4 4L10 18H6v-4L16 4Z"/>'
  };
  const ico = (name,size=18) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round">${icons[name]||icons.star}</svg>`;
  const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const id = () => (globalThis.crypto?.randomUUID?.() || `hs_${Date.now()}_${Math.random().toString(36).slice(2,10)}`);
  const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const prettyDate = s => { const d = new Date(`${s}T12:00:00`); return Number.isNaN(d.getTime())?esc(s):new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'short',year:'numeric'}).format(d); };
  const weekDay = () => new Date().getDay();
  const fmt = n => new Intl.NumberFormat('de-DE',{maximumFractionDigits:1}).format(n||0);
  const num = (v, fallback=0) => { const n = Number(String(v).replace(',','.'));return Number.isFinite(n)?n:fallback;};
  const clamp = (v,a,b) => Math.min(Math.max(v,a),b);
  const fallbackExercises = [
    ['Brustpresse','Brust',120],['Schrägbankdrücken','Brust',150],['Schrägbank Smith','Brust',150],['Butterfly','Brust',90],
    ['Latzug','Rücken',120],['Breites Kabelrudern','Rücken',120],['Enges Kabelrudern','Rücken',120],['T-Bar Row','Rücken',150],
    ['Seitheben','Schultern',90],['Seitheben Maschine','Schultern',90],['Reverse Fly','Schultern',90],
    ['Preacher Curls','Bizeps',90],['Bizeps Curl Kabel','Bizeps',90],['Hammer Curls','Bizeps',90],['Hammer Curl Kabel','Bizeps',90],
    ['Trizepsdrücken','Trizeps',90],['Trizeps Extension Kabel','Trizeps',90],['Trizeps Pushdown','Trizeps',90],['Overhead Trizeps Extension','Trizeps',90],
    ['Beinpresse','Beine',180],['Beinbeuger','Beine',90],['Beinbeuger liegend','Beine',90],['Beinstrecker','Beine',90],['Romanian Deadlift','Beine',150],['Wadenheben','Beine',90],
    ['Cable Crunch','Bauch',75],['Unterarm-Curls','Unterarme',75]
  ].map(([name,group,rest])=>({name,group,rest}));
  const exerciseMap = Object.fromEntries(fallbackExercises.map(x=>[x.name.toLowerCase(),x]));
  const ex = (name,sets=2,reps='8–12',rest) => ({id:id(),name,sets,reps,rest:rest||exerciseMap[name.toLowerCase()]?.rest||120});
  const createDefaults = () => {
    const templates = [
      {id:id(),name:'Oberkörper',short:'MO',day:1,exercises:[ex('Brustpresse',2,'6–10'),ex('Latzug',2,'8–12'),ex('Schrägbankdrücken',2,'8–12'),ex('Breites Kabelrudern',2,'8–12'),ex('Seitheben',2,'12–15'),ex('Preacher Curls',2,'10–12'),ex('Trizepsdrücken',2,'10–12')]},
      {id:id(),name:'Unterkörper',short:'DI',day:2,exercises:[ex('Beinpresse',3,'8–12'),ex('Beinbeuger',2,'10–12'),ex('Romanian Deadlift',2,'8–10'),ex('Beinstrecker',2,'10–15'),ex('Wadenheben',3,'10–15'),ex('Cable Crunch',2,'10–15')]},
      {id:id(),name:'Ganzkörper',short:'DO',day:4,exercises:[ex('Beinpresse',2,'8–12'),ex('Schrägbankdrücken',2,'8–12'),ex('Enges Kabelrudern',2,'8–12'),ex('Beinbeuger',2,'10–12'),ex('Latzug',2,'8–12'),ex('Reverse Fly',2,'12–15'),ex('Hammer Curls',2,'10–12'),ex('Unterarm-Curls',2,'12–15')]}
    ];
    return {version:1,createdAt:new Date().toISOString(),settings:{nickname:'Hunter',restDefault:120,questMode:'gentle',oauthClientId:'',spreadsheetId:'',autoSync:false},templates,workouts:[],active:null,quests:{},xp:{workoutIds:[]},sync:{lastPush:null}};
  };
  function load(){try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(Array.isArray(data.templates)&&Array.isArray(data.workouts)&&data.version===1){data.settings={...createDefaults().settings,...data.settings};data.quests ||= {};data.xp ||= {workoutIds:[]};data.sync ||= {lastPush:null};return data;}}}catch(e){console.error('Load failed',e)}return createDefaults();}
  let state = load();
  let tab = 'home';
  let selectedProgress = 'Brustpresse';
  let selectedHistory = null;
  let elapsedRest = false;
  let token = null;
  let syncInProgress = false;
  let toastTimeout;
  let templateClickHandler = null;
  const save = () => { try {localStorage.setItem(KEY,JSON.stringify(state));return true;}catch(e){toast('Speichern fehlgeschlagen – bitte Speicherplatz prüfen.');return false;} };
  save();
  const notify = msg => { const node=document.getElementById('toast');if(!node)return;node.innerHTML=`<div class="toast-msg">${esc(msg)}</div>`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>node.innerHTML='',3600); };
  const toast = msg => notify(msg);
  const btn = (label,action,cls='button',attrs='') => `<button class="${cls}" data-action="${esc(action)}" ${attrs}>${label}</button>`;
  const activeSets = () => state.active?.exercises.flatMap(e=>e.sets).filter(s=>s.done).length || 0;
  const workload = w => w.exercises.reduce((t,e)=>t+e.sets.filter(s=>s.done).reduce((a,s)=>a+num(s.kg)*num(s.reps),0),0);
  const workoutSets = w => w.exercises.reduce((t,e)=>t+e.sets.filter(s=>s.done).length,0);
  const levelInfo = xp => {let level=1,left=xp,needed=120;while(left>=needed&&level<999){left-=needed;level++;needed=Math.round(120+level*28);}return {level,into:left,needed,percent:clamp(left/needed*100,0,100)};};
  const earnedXP = () => Object.values(state.quests||{}).reduce((a,day)=>a+Object.entries(day.completed||{}).reduce((b,[k,v])=>b+(v ? (day.items||[]).find(x=>x.id===k)?.xp||0:0),0),0)+state.workouts.filter(w=>w.source!=='Strong-Screenshot').length*80;
  function activeTimer(){const t=state.active?.restTimer;return t && t.end > 0 ? t : null;}
  const remain = () => Math.max(0,Math.ceil(((activeTimer()?.end||0)-Date.now())/1000));
  const hhmm = s => {let x=Math.max(0,Math.floor(s));return `${String(Math.floor(x/60)).padStart(2,'0')}:${String(x%60).padStart(2,'0')}`;};
  const subtitle = {'home':'Dein Fortschritt. Deine Mission.', 'training':'Dein Training gehört dir. Jede Wiederholung zählt.', 'quests':'Neue Herausforderungen – unabhängig vom Trainingsplan.', 'progress':'Alle Leistungen an einem Ort.', 'settings':'Deine Daten. Deine Einstellungen.'};
  const navs=[['home','Übersicht','home'],['training','Training','dumbbell'],['quests','Quests','scroll'],['progress','Fortschritt','chart'],['settings','Einstellungen','gear']];
  function shell(inner){
    document.getElementById('app').innerHTML = `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-badge">${ico('shield',24)}</span><div><div class="brand-title">HUNTER SYSTEM</div><div class="brand-sub">Awaken your potential</div></div></div><div class="navlist">${navs.map(([key,name,icon])=>`<button class="navbtn ${tab===key?'active':''}" data-tab="${key}">${ico(icon)}${name}</button>`).join('')}</div><div class="sidebar-bottom"><div class="side-sigil">${ico('star',17)} SOLO HUNTER</div><div>Lokale Speicherung · Offline bereit</div><div style="margin-top:6px;line-height:1.5">Deine Werte bleiben auf diesem Gerät, bis du sie synchronisierst oder exportierst.</div></div></aside><div class="mobile-head"><div class="brand"><span class="brand-badge">${ico('shield',20)}</span><div><div class="brand-title">HUNTER SYSTEM</div><div class="brand-sub">Solo Edition</div></div></div><span class="badge">BETA 1</span></div><main class="main">${inner}</main><nav class="bottom-nav" aria-label="Hauptnavigation">${navs.map(([key,name,icon])=>`<button class="mobile-navbtn ${tab===key?'active':''}" data-tab="${key}">${ico(icon,19)}<span>${name}</span></button>`).join('')}</nav></div>`;
  }
  const header = (eyebrow,title,description,actions='')=>`<header class="page-header"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 class="page-title">${title}</h1><p class="page-description">${esc(description)}</p></div>${actions?`<div class="header-actions">${actions}</div>`:''}</header>`;
  const weekdayName={1:'Montag',2:'Dienstag',3:'Mittwoch',4:'Donnerstag',5:'Freitag',6:'Samstag',0:'Sonntag'};
  const todayPlan = () => state.templates.find(t=>t.day===weekDay());
  function generateQuests(date){
    const isTraining= [1,2,4].includes(new Date(`${date}T12:00:00`).getDay());
    const seed=[...date].reduce((a,c)=>a*17+c.charCodeAt(0),71);
    const pick=(items,offset)=>items[Math.abs(seed+offset)%items.length];
    const movement=state.settings.questMode==='normal' ?
      [{name:'10 Liegestütze',detail:'Nur wenn du frisch bist; auf Knien als Alternative.',xp:30},{name:'10 Minuten spazieren',detail:'Locker und ohne Leistungsdruck.',xp:25},{name:'15 freie Kniebeugen',detail:'Sauber und ohne Tempozwang.',xp:25},{name:'5 Minuten Mobility',detail:'Sanfte Bewegung für Gelenke und Haltung.',xp:25}] :
      [{name:'10 Minuten spazieren',detail:'Lockere Bewegung, ohne dich auszupowern.',xp:25},{name:'5 Minuten Mobility',detail:'Sanfte Beweglichkeit statt Extratraining.',xp:25},{name:'3 Minuten leicht dehnen',detail:'Ruhig atmen, keine Schmerzen provozieren.',xp:20},{name:'Kurze Bewegungspause',detail:'5 Minuten aufstehen und entspannt bewegen.',xp:20}];
    return [
      {id:'movement',...pick(movement,0),type:'Bewegung',icon:'run'},
      {id:'nutrition',...pick([{name:'Protein-Ziel prüfen',detail:'Prüfe deine persönliche Zielvorgabe in Yazio.',xp:30},{name:'Mahlzeiten für morgen planen',detail:'Bereite eine Mahlzeit oder einen Snack vor.',xp:30},{name:'Ausreichend essen',detail:'Versuche dein individuelles Kalorienziel zu erreichen.',xp:30}],3),type:'Ernährung',icon:'heart'},
      {id:'recovery',...pick([{name:'Schlafzeit einplanen',detail:'Plane ein ausreichend langes Schlafzeitfenster ein.',xp:35},{name:'Abendroutine beginnen',detail:'30 Minuten vor dem Schlafengehen runterfahren.',xp:35},{name:'Erholung bewusst priorisieren',detail:'Weniger ist manchmal mehr – gönne dir Ruhe.',xp:35}],8),type:'Regeneration',icon:'moon'}
    ].map(q=>({...q,detail:q.detail+(isTraining&&q.id==='movement'?' Extra-Kraftübungen sind heute nicht nötig.':'')}));
  }
  function questDay(date=today()){
    if(!state.quests[date]){state.quests[date]={items:generateQuests(date),completed:{},createdAt:new Date().toISOString()};save();}
    return state.quests[date];
  }
  function questHtml(limit=false){const d=questDay();let arr=d.items;if(limit)arr=arr.slice(0,3);return arr.map(q=>`<div class="quest-row ${d.completed[q.id]?'done':''}"><button class="quest-check ${d.completed[q.id]?'checked':''}" aria-label="${esc(q.name)} abschließen" data-action="quest-toggle" data-id="${esc(q.id)}">${ico('check',16)}</button><div style="min-width:0;flex:1"><div class="quest-title">${esc(q.name)}</div><div class="quest-sub">${esc(q.detail)}</div></div><div class="xp">+${q.xp} XP</div></div>`).join('');}
  function bestSetsByExercise(){const map={};for(const w of state.workouts){for(const e of w.exercises){for(const s of e.sets){if(!s.done)continue;const key=e.name.toLowerCase();const score=num(s.kg)*(1+num(s.reps)/30);const obj=map[key];if(!obj||score>obj.score){map[key]={name:e.name,kg:num(s.kg),reps:num(s.reps),score,date:w.date};}}}}return Object.values(map).sort((a,b)=>a.name.localeCompare(b.name,'de'));}
  function home(){const l=levelInfo(earnedXP());const w=todayPlan();const totalQuests=questDay().items.length;const done=Object.values(questDay().completed).filter(Boolean).length;const historic=state.workouts[state.workouts.length-1];const sessions=state.workouts.filter(x=>x.source!=='Strong-Screenshot').length;
    return header('SYSTEM / DASHBOARD',`Willkommen zurück, <span class="big-gradient">${esc(state.settings.nickname)}</span>.`,subtitle.home,
      btn(`${ico('dumbbell')} ${state.active?'Training fortsetzen':'Training starten'}`,'go-training','button primary'))+`<section class="grid-2"><div class="stack"><div class="panel panel-hero"><div class="eyebrow">SOLO HUNTER // STATUS</div><div class="hero-level">Level ${l.level}</div><p class="panel-desc" style="max-width:390px">Dein Hunter wächst durch absolvierte Trainings und tägliche Quests. Erholung ist Teil des Fortschritts.</p><div class="label-value" style="margin:20px 0 7px;font-size:11px;color:#c8cef1"><span>Level-Fortschritt</span><span>${l.into} / ${l.needed} XP</span></div><div class="level-line"><div class="level-fill" style="width:${l.percent}%"></div></div></div><div class="stat-grid"><div class="stat-card"><div class="stat-label">Trainings gesamt</div><div class="stat-number">${state.workouts.length}</div><div class="stat-foot">davon ${sessions} in dieser App</div></div><div class="stat-card"><div class="stat-label">Heute Quests</div><div class="stat-number">${done}/${totalQuests}</div><div class="stat-foot">Ohne XP-Strafen</div></div><div class="stat-card"><div class="stat-label">Übungsrekorde</div><div class="stat-number">${bestSetsByExercise().length}</div><div class="stat-foot">aus deiner Historie</div></div></div><div class="panel"><div class="panel-head"><h2 class="panel-title">Dein nächstes Training</h2><span class="badge subdued">${esc(weekdayName[weekDay()])}</span></div>${w?`<div class="workout-title">${esc(w.name)}</div><p class="panel-desc">${w.exercises.length} Übungen · ${w.exercises.reduce((n,e)=>n+e.sets,0)} geplante Arbeitssätze</p><div class="workout-rows">${w.exercises.slice(0,5).map(e=>`<div class="exercise-line"><span>${esc(e.name)}</span><span class="muted">${e.sets} × ${esc(e.reps)}</span></div>`).join('')}${w.exercises.length>5?`<div class="muted tiny">+ ${w.exercises.length-5} weitere Übungen</div>`:''}</div>${btn(`${ico('play')} Training auswählen`,'go-training','button secondary full')}`:`<div class="empty">Heute ist im Standardplan ein <strong>Ruhetag</strong>.<br>Du kannst trotzdem deine Trainingspläne ansehen.</div>${btn('Pläne ansehen','go-training','button ghost full')}`}</div></div><div class="stack"><div class="panel"><div class="panel-head"><h2 class="panel-title">Tägliche Quests</h2><span class="badge">${done}/${totalQuests} abgeschlossen</span></div><p class="panel-desc">Unabhängig vom Gym · Kleine Aufgaben mit Rücksicht auf deine Regeneration.</p>${questHtml(true)}<div style="margin-top:16px">${btn('Alle Quests ansehen '+ico('chevron'),'go-quests','button ghost full')}</div></div><div class="panel"><div class="panel-head"><h2 class="panel-title">Letztes Training</h2>${btn('Historie','go-progress','button small ghost')}</div>${historic?`<div class="workout-title">${esc(historic.name)}</div><div class="meta" style="margin-top:8px">${ico('calendar',13)} ${prettyDate(historic.date)} · ${workoutSets(historic)} Sätze</div><div class="separator"></div><div class="key-value"><span>Trainingsvolumen*</span><span>${fmt(workload(historic))} kg</span></div><p class="hint">*Summe aus kg × Wiederholungen; zwischen Geräten nicht direkt vergleichbar.</p>`:`<div class="empty">Noch keine Einheiten gespeichert.</div>`}</div><div class="helper">${ico('info',15)} <strong>Hinweis:</strong> Deine App funktioniert lokal. Für ChatGPT-Auswertungen synchronisiere später mit Google Sheets oder exportiere deine Daten.</div></div></section>`;
  }
  function lastSetFor(name, idx){for(let i=state.workouts.length-1;i>=0;i--){const e=state.workouts[i].exercises.find(x=>x.name.toLowerCase()===name.toLowerCase());if(e){const hits=e.sets.filter(x=>x.done);const s=hits[Math.min(idx,hits.length-1)];if(s)return s;}}return null;}
  function buildActiveExercise(t){return {id:id(),name:t.name,reps:t.reps,rest:t.rest||state.settings.restDefault,sets:Array.from({length:t.sets},(_,idx)=>{const old=lastSetFor(t.name,idx);return {id:id(),kg:old?.kg||0,reps:old?.reps||0,rir:old?.rir??null,done:false};})};}
  function beginWorkout(templateId){if(state.active){if(!confirm('Ein Training läuft bereits. Möchtest du es verwerfen und ein anderes beginnen?'))return;}
    const temp=state.templates.find(t=>t.id===templateId);if(!temp)return;
    state.active={id:id(),date:today(),name:temp.name,templateId:temp.id,startedAt:Date.now(),exercises:temp.exercises.map(buildActiveExercise),notes:'',restTimer:null};elapsedRest=false;save();tab='training';render();toast('Training gestartet. Viel Erfolg!');
  }
  function finishWorkout(){if(!state.active)return;const total=activeSets();if(!total){toast('Markiere zuerst mindestens einen Satz als erledigt.');return;}
    if(!confirm(`${total} abgeschlossene Sätze als Training speichern?`))return;
    const a=state.active;const session={id:a.id,date:a.date,name:a.name,source:'Hunter-System',duration:Math.max(1,Math.round((Date.now()-a.startedAt)/60000)),notes:a.notes,exercises:a.exercises.map(e=>({...e,sets:e.sets.filter(s=>s.done)})).filter(e=>e.sets.length)};
    state.workouts.push(session);state.active=null;save();toast(`Training gespeichert · +80 XP`);tab='progress';selectedHistory=session.id;render();maybeAutoSync();
  }
  function timerHTML(){const t=activeTimer();if(!t)return '';const left=remain();return `<div class="timer ${left===0?'finished':''}" id="rest-timer"><div><div class="timer-label">${left===0?'PAUSE VORBEI':'REST TIMER · PAUSE'}</div><div class="timer-time" id="timer-value">${hhmm(left)}</div></div><div class="inline-actions">${btn('−15 s','rest-minus','button small secondary')}${btn('+15 s','rest-plus','button small secondary')}${btn('Beenden','rest-skip','button small ghost')}</div></div>`;}
  function activeTraining(){const a=state.active;const setTotal=a.exercises.reduce((n,e)=>n+e.sets.length,0);return `<div class="active-banner"><div style="color:#b5a5ff">${ico('timer',22)}</div><div style="flex:1"><strong style="font-size:13px">${esc(a.name)} läuft</strong><div class="hint">${activeSets()} / ${setTotal} Sätze erledigt · <span id="active-elapsed">${hhmm(Math.round((Date.now()-a.startedAt)/1000))}</span> vergangen</div></div>${btn('Abbrechen','discard-workout','button small ghost')}</div>${timerHTML()}<div class="panel"><div class="panel-head"><div><h2 class="panel-title">${esc(a.name)}</h2><p class="panel-desc">Gewichte und Wiederholungen kannst du in jedem Satz ändern.</p></div><span class="badge green">LIVE</span></div>${a.exercises.map((e,ei)=>`<section class="workout-exercise"><div class="exercise-top"><div><h3>${ei+1}. ${esc(e.name)}</h3><div class="hint">Ziel: ${esc(e.reps)} Wdh. · ${Math.round(e.rest/60*10)/10} Min. Pause</div></div><div class="inline-actions">${btn(ico('edit'),`edit-active-exercise|${ei}`,'button small square ghost','aria-label="Übung bearbeiten"')}${btn(ico('trash'),`remove-active-exercise|${ei}`,'button small square ghost','aria-label="Übung entfernen"')}</div></div><div class="hint" style="margin-bottom:9px">RIR = saubere Wiederholungen, die noch möglich gewesen wären. Aktuell ca. 2–3 RIR anpeilen.</div><div class="sets-head"><span>Satz</span><span>kg</span><span>Wdh.</span><span>RIR</span><span>Fertig</span></div>${e.sets.map((s,si)=>`<div class="set-row"><span class="set-num">${si+1}</span><input class="input" type="number" inputmode="decimal" min="0" max="1000" step="0.5" data-set-input="kg" data-ex="${ei}" data-set="${si}" value="${esc(s.kg)}" aria-label="Gewicht Satz ${si+1} bei ${esc(e.name)}"><input class="input" type="number" inputmode="numeric" min="0" max="500" step="1" data-set-input="reps" data-ex="${ei}" data-set="${si}" value="${esc(s.reps)}" aria-label="Wiederholungen Satz ${si+1} bei ${esc(e.name)}"><select class="select" data-set-input="rir" data-ex="${ei}" data-set="${si}" aria-label="RIR"><option value="" ${s.rir==null?'selected':''}>–</option>${[0,1,2,3,4,5].map(k=>`<option value="${k}" ${s.rir===k?'selected':''}>${k}</option>`).join('')}</select><button class="set-check ${s.done?'checked':''}" data-action="complete-set" data-ex="${ei}" data-set="${si}" aria-label="Satz ${si+1} ${s.done?'als offen markieren':'abschließen'}">${ico('check',19)}</button></div>`).join('')}<div class="inline-actions" style="margin-top:13px">${btn(`${ico('plus')} Satz hinzufügen`,`add-active-set|${ei}`,'button small ghost')}${btn(`− Satz`,`remove-active-set|${ei}`,'button small ghost',e.sets.length<=1?'disabled':'')}</div></section>`).join('')}<div class="inline-actions" style="margin-top:15px">${btn(`${ico('plus')} Übung hinzufügen`,'add-active-exercise','button secondary')}</div><div class="separator"></div><div class="field"><label>Notizen zu diesem Training</label><textarea class="textarea" id="active-notes" placeholder="Wie lief das Training? Schmerzen, Technik, Tagesform ...">${esc(a.notes)}</textarea></div><div style="margin-top:16px">${btn(`${ico('check')} Training beenden & speichern`,'finish-workout','button primary full')}</div></div>`;}
  function training(){return header('SYSTEM / TRAINING','Dein Trainingsbereich',subtitle.training,state.active?'':btn(`${ico('plus')} Neuer Plan`,'new-template','button primary'))+(state.active?activeTraining():`<div class="helper" style="margin-bottom:16px">${ico('calendar',15)} Dein Ausgangsplan: <strong>Montag Oberkörper, Dienstag Unterkörper, Donnerstag Ganzkörper.</strong> Jeder Plan ist veränderbar. Ein Ruhetag darf auch ein Ruhetag bleiben.</div><div class="grid-3">${state.templates.map(t=>`<div class="workout-card"><div class="label-value"><span class="badge">${esc(t.short||weekdayName[t.day]||'FREI')}</span>${btn(ico('edit'),`edit-template|${t.id}`,'button small square ghost','aria-label="Plan bearbeiten"')}</div><div><div class="workout-title">${esc(t.name)}</div><div class="workout-count">${t.exercises.length} Übungen · ${t.exercises.reduce((n,e)=>n+e.sets,0)} Sätze</div></div><div class="workout-rows">${t.exercises.slice(0,7).map(e=>`<div class="exercise-line"><span>${esc(e.name)}</span><span class="muted">${e.sets} × ${esc(e.reps)}</span></div>`).join('')}${t.exercises.length>7?`<div class="muted tiny">+ ${t.exercises.length-7} weitere</div>`:''}</div>${btn(`${ico('play')} Training starten`,`start-workout|${t.id}`,'button primary full')}</div>`).join('')}</div><div style="margin-top:16px" class="helper">${ico('info',15)} ${state.templates.length?'Du kannst vor oder während eines Trainings Gewichte, Wiederholungen und Übungen ändern. Alte Trainingseinträge bleiben erhalten.':'Erstelle einen ersten Plan.'}</div>`);}
  function quests(){const q=questDay();const done=q.items.filter(x=>q.completed[x.id]).length;return header('SYSTEM / DAILY QUESTS','Deine heutigen Quests',subtitle.quests,btn(`${ico('refresh')} Neue Bewegungsquest`,'reroll-quest','button secondary'))+`<div class="grid-2"><div class="stack"><div class="panel panel-hero"><div class="eyebrow">TAGESMISSION · ${prettyDate(today())}</div><div class="hero-level">${done}<span style="color:#99a9cc;font-size:27px"> / ${q.items.length}</span></div><p class="panel-desc">Quests abgeschlossen. Kein Punkteabzug, wenn du einen Tag auslässt. Nutze die Pause, die du brauchst.</p><div class="level-line" style="margin-top:18px"><div class="level-fill" style="width:${done/q.items.length*100}%"></div></div></div><div class="panel"><div class="panel-head"><h2 class="panel-title">Täglicher Quest-Log</h2><span class="badge">${q.items.reduce((s,x)=>s+x.xp,0)} XP möglich</span></div>${questHtml()}<p class="hint" style="margin-top:14px">Die Quests sind unabhängig vom Trainingsplan. Markiere sie nur, wenn du sie tatsächlich erledigt hast.</p></div></div><div class="stack"><div class="panel"><div class="panel-head"><h2 class="panel-title">Deine Entwicklung</h2>${ico('star',20)}</div><div class="hero-level" style="font-size:36px">${earnedXP()} XP</div><div class="panel-desc">Level ${levelInfo(earnedXP()).level} · XP durch Quests und abgeschlossene Trainings dieser App.</div><div class="separator"></div><div class="key-value"><span>Heute verdient</span><span>${q.items.filter(x=>q.completed[x.id]).reduce((s,x)=>s+x.xp,0)} XP</span></div><div class="key-value"><span>Quests heute</span><span>${done} / ${q.items.length}</span></div></div><div class="panel"><div class="panel-head"><h2 class="panel-title">Quest-Modus</h2><span class="badge green">Regeneration zählt</span></div><p class="panel-desc">Momentan empfehle ich dir aufgrund deiner bisherigen Müdigkeit sanfte Quests. Später kannst du in den Einstellungen moderate Körpergewichtsübungen aktivieren.</p>${btn('Quest-Einstellungen','go-settings','button ghost full')}</div></div></div>`;}
  function exerciseHistory(name){return state.workouts.flatMap(w=>w.exercises.filter(e=>e.name===name).map(e=>({date:w.date,workout:w.name,sets:e.sets.filter(s=>s.done),id:w.id}))).filter(e=>e.sets.length).sort((a,b)=>a.date.localeCompare(b.date));}
  function lineChart(data){if(!data.length)return `<div class="empty">Noch keine abgeschlossenen Sätze für diese Übung.</div>`;if(data.length===1)return `<div class="empty"><strong>Erster Messpunkt: ${fmt(data[0].y)} kg</strong><br>Nach deinem nächsten Training erscheint hier ein Verlauf.</div>`;const width=590,height=210,p={left:45,right:15,top:18,bottom:35};const vals=data.map(x=>x.y);const min=Math.min(...vals),max=Math.max(...vals);const floor=Math.max(0,min-(max-min||Math.max(10,min*.3))*.3);const ceil=max+(max-min||Math.max(10,max*.3))*.3;const x=i=>p.left+(width-p.left-p.right)*i/(data.length-1);const y=v=>p.top+(height-p.top-p.bottom)*(ceil-v)/(ceil-floor||1);const points=data.map((d,i)=>`${x(i)},${y(d.y)}`).join(' ');let grid='';for(let i=0;i<4;i++){const val=floor+(ceil-floor)*i/3;const yy=y(val);grid+=`<line class="chart-grid" x1="${p.left}" y1="${yy}" x2="${width-p.right}" y2="${yy}"/><text class="chart-label" x="${p.left-8}" y="${yy+4}" text-anchor="end">${fmt(val)}</text>`;}const xticks=[0,Math.floor((data.length-1)/2),data.length-1];for(const idx of [...new Set(xticks)])grid+=`<text class="chart-label" x="${x(idx)}" y="${height-9}" text-anchor="middle">${esc(new Date(`${data[idx].date}T12:00:00`).toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'}))}</text>`;return `<svg class="progress-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Verlauf des höchsten verwendeten Satzgewichts für ${esc(selectedProgress)}"><title>Trainingsgewichte in kg im Zeitverlauf</title>${grid}<polyline class="chart-line" points="${points}"/>${data.map((v,i)=>`<circle class="chart-point" cx="${x(i)}" cy="${y(v.y)}" r="5"><title>${esc(v.date)}: ${fmt(v.y)} kg</title></circle>`).join('')}</svg>`;}
  function historyDetail(w){return `<div class="panel"><div class="panel-head"><div><h2 class="panel-title">${esc(w.name)}</h2><p class="panel-desc">${prettyDate(w.date)} · ${w.duration||'–'} Minuten · ${workoutSets(w)} Sätze</p></div>${btn(ico('x'),'close-history','button small square ghost')}</div><div class="key-value"><span>Gewichtsvolumen*</span><span>${fmt(workload(w))} kg</span></div><div class="key-value"><span>Quelle</span><span>${esc(w.source||'App')}</span></div>${w.notes?`<p class="helper">${esc(w.notes)}</p>`:''}${w.exercises.map(e=>`<div class="workout-exercise"><strong class="small-text">${esc(e.name)}</strong><div class="table-wrap"><table class="data-table"><thead><tr><th>Satz</th><th>Gewicht</th><th>Wdh.</th><th>RIR</th></tr></thead><tbody>${e.sets.filter(s=>s.done).map((s,i)=>`<tr><td>${i+1}</td><td>${fmt(s.kg)} kg</td><td>${fmt(num(s.reps))}</td><td>${s.rir==null?'–':fmt(num(s.rir))}</td></tr>`).join('')}</tbody></table></div></div>`).join('')}<p class="hint">*Gewichtsvolumen ist keine Messung der absoluten Kraft.</p><div style="margin-top:14px">${btn(`${ico('trash')} Eintrag löschen`,`delete-history|${w.id}`,'button danger small')}</div></div>`;}
  function progress(){const hist=state.workouts.slice().sort((a,b)=>b.date.localeCompare(a.date));const choices=[...new Set(state.workouts.flatMap(w=>w.exercises.map(e=>e.name)))].sort((a,b)=>a.localeCompare(b,'de'));if(!choices.includes(selectedProgress))selectedProgress=choices[0]||'';const entries=exerciseHistory(selectedProgress);const points=entries.map(e=>({date:e.date,y:Math.max(...e.sets.map(s=>num(s.kg)))}));const best=bestSetsByExercise().find(e=>e.name===selectedProgress);const selected=hist.find(w=>w.id===selectedHistory);return header('SYSTEM / PROGRESS','Dein Fortschritt',subtitle.progress,btn(`${ico('download')} Daten exportieren`,'export-csv','button secondary'))+`<div class="grid-2"><div class="stack"><div class="panel"><div class="panel-head"><h2 class="panel-title">Entwicklung pro Übung</h2><span class="badge subdued">kg / Training</span></div><div class="field"><label>Übung auswählen</label><select class="select" id="progress-exercise">${choices.map(n=>`<option value="${esc(n)}" ${n===selectedProgress?'selected':''}>${esc(n)}</option>`).join('')}</select></div><div style="margin:18px 0 8px">${lineChart(points)}</div>${best?`<div class="stat-grid"><div class="stat-card"><div class="stat-label">Bester Satz*</div><div class="stat-number">${fmt(best.kg)} <span style="font-size:12px">kg</span></div><div class="stat-foot">${best.reps} Wdh.</div></div><div class="stat-card"><div class="stat-label">Einträge</div><div class="stat-number">${entries.length}</div></div><div class="stat-card"><div class="stat-label">Letzter Wert</div><div class="stat-number">${fmt(points.at(-1)?.y)} <span style="font-size:12px">kg</span></div></div></div><p class="hint" style="margin-top:8px">*Bester Satz nach geschätzter Leistungsformel; ein isolierter Gerätewert ist kein allgemeiner Krafttest.</p>`:''}</div><div class="panel"><div class="panel-head"><h2 class="panel-title">Persönliche Übungsbestwerte</h2><span class="badge">${bestSetsByExercise().length} Übungen</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Übung</th><th>Gewicht</th><th>Wdh.</th></tr></thead><tbody>${bestSetsByExercise().map(v=>`<tr><td>${esc(v.name)}</td><td>${fmt(v.kg)} kg</td><td>${v.reps}</td></tr>`).join('')}</tbody></table></div></div></div><div class="stack"><div class="panel"><div class="panel-head"><h2 class="panel-title">Trainingshistorie</h2><span class="badge subdued">${hist.length} Einträge</span></div><div class="history-list">${hist.map(w=>`<div class="history-item"><div class="history-item-main"><div class="history-item-name">${esc(w.name)}</div><div class="meta">${prettyDate(w.date)} · ${workoutSets(w)} Sätze ${w.source==='Strong-Screenshot'?'· Import':''}</div></div>${btn(ico('chevron'),`view-history|${w.id}`,'button small square ghost','aria-label="Eintrag öffnen"')}</div>`).join('')||'<div class="empty">Noch keine Einheiten gespeichert.</div>'}</div></div>${selected?historyDetail(selected):`<div class="helper">${ico('info',16)} Tippe in der Trainingshistorie auf einen Eintrag, um alle Sätze, Gewichte und Wiederholungen zu sehen.</div>`}</div></div>`;}
  function settings(){const s=state.settings;return header('SYSTEM / SETTINGS','Einstellungen',subtitle.settings)+`<div class="grid-2"><div class="stack"><div class="panel"><div class="panel-head"><h2 class="panel-title">Persönliche Einstellungen</h2>${ico('gear',19)}</div><div class="setting-block"><div class="field"><label>Hunter-Name</label><input class="input" id="settings-nickname" value="${esc(s.nickname)}" maxlength="32"></div><div class="form-row"><div class="field"><label>Standardpause (Sek.)</label><input class="input" type="number" min="30" max="600" step="15" id="settings-rest" value="${esc(s.restDefault)}"></div><div class="field"><label>Daily-Quest-Modus</label><select class="select" id="settings-quest"><option value="gentle" ${s.questMode==='gentle'?'selected':''}>Sanft (empfohlen)</option><option value="normal" ${s.questMode==='normal'?'selected':''}>Normal</option></select></div></div>${btn('Einstellungen speichern','save-settings','button primary full')}</div></div><div class="panel"><div class="panel-head"><h2 class="panel-title">Datensicherung</h2>${ico('download',20)}</div><p class="panel-desc">Aktuell werden alle Daten lokal in diesem Browser gespeichert. Bei Browser-Datenlöschung oder Gerätewechsel können sie verloren gehen.</p><div class="quick-actions" style="margin-top:15px">${btn(`${ico('download')} JSON-Backup`,'export-json','button secondary')}${btn(`${ico('download')} CSV-Export`,'export-csv','button ghost')}${btn(`${ico('upload')} Backup importieren`,'import-json','button ghost')}</div><input type="file" accept="application/json,.json" id="file-import" style="display:none"><div class="helper warning" style="margin-top:15px">${ico('alert',16)} Sichere regelmäßig eine JSON-Datei, solange Google Sheets nicht eingerichtet ist.</div></div></div><div class="stack"><div class="panel"><div class="panel-head"><h2 class="panel-title">Google Sheets</h2><span class="badge ${s.spreadsheetId?'green':'subdued'}">${s.spreadsheetId?'Konfiguriert':'Nicht eingerichtet'}</span></div><p class="panel-desc">Optional: Mit deinem eigenen Google-Konto synchronisieren. Danach kannst du die Tabelle über einen verbundenen Google-Drive-Zugriff in ChatGPT analysieren lassen.</p><div class="setting-block" style="margin-top:15px"><div class="field"><label>OAuth-Client-ID (Google Cloud)</label><input class="input" id="settings-clientid" placeholder="...apps.googleusercontent.com" value="${esc(s.oauthClientId)}"></div><div class="field"><label>Google-Sheets-ID (optional, kann neu erstellt werden)</label><input class="input" id="settings-sheetid" placeholder="ID aus der Google-Sheets-URL" value="${esc(s.spreadsheetId)}"></div><div class="quick-actions">${btn('Zugangsdaten speichern','save-google-settings','button secondary')}${btn(`${ico('cloud')} Google verbinden`,'google-connect','button primary',!window.isSecureContext?'disabled title="Benötigt HTTPS"':'')}</div><div class="quick-actions">${btn('Neue Tabelle erstellen','google-create','button ghost',!token?'disabled':'')}${btn('In Google Sheets sichern','google-push','button ghost',!token?'disabled':'')}${btn('Aus Google Sheets laden','google-pull','button ghost',!token?'disabled':'')}</div><label class="small-text" style="display:flex;gap:9px;align-items:center;color:#b7c7df"><input type="checkbox" id="settings-autosync" ${s.autoSync?'checked':''}>Nach einem Training automatisch synchronisieren (nur solange Google verbunden ist)</label>${s.spreadsheetId?`<a class="button ghost" href="https://docs.google.com/spreadsheets/d/${encodeURIComponent(s.spreadsheetId)}/edit" rel="noopener noreferrer" target="_blank">${ico('external')} Tabelle öffnen</a>`:''}<p class="sync-note">${state.sync.lastPush?'Letzte erfolgreiche Sicherung: '+new Date(state.sync.lastPush).toLocaleString('de-DE'):'Noch keine erfolgreiche Cloud-Sicherung.'}</p><div class="helper"><strong>Einmalige Google-Einrichtung:</strong> Bei Google Cloud die Sheets API aktivieren, einen OAuth-Client vom Typ <em>Webanwendung</em> erstellen und die HTTPS-Adresse deiner PWA als erlaubten JavaScript-Ursprung eintragen. Danach Client-ID hier einfügen. Details in der README-Datei.</div></div></div><div class="panel"><h2 class="panel-title">Sicherheit und Gesundheit</h2><p class="panel-desc">Die App ist ein Trainingstagebuch, kein medizinisches Messgerät. Quests sind freiwillig. Bei Schmerzen, starker Müdigkeit oder Krankheit keine Belastung für XP erzwingen. Wegen deiner seit Monaten bestehenden Erschöpfung ist eine ärztliche Abklärung sinnvoll.</p></div></div></div>`;}
  function render(){shell(tab==='home'?home():tab==='training'?training():tab==='quests'?quests():tab==='progress'?progress():settings());}
  function addModal(title,html){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-top"><h2>${esc(title)}</h2><button class="modal-close" data-action="close-modal" aria-label="Schließen">×</button></div><div class="modal-body">${html}</div></div></div>`;}
  function closeModal(){document.getElementById('modal-root').innerHTML='';if(templateClickHandler){document.removeEventListener('click',templateClickHandler,true);templateClickHandler=null;}}
  function templateModal(templateId){if(templateClickHandler){document.removeEventListener('click',templateClickHandler,true);templateClickHandler=null;}const template=state.templates.find(t=>t.id===templateId);const create=!template;const t=template||{id:null,name:'Neuer Trainingsplan',day:null,exercises:[]};let working=JSON.parse(JSON.stringify(t));
    const draw = () => {const host=document.getElementById('modal-root');if(!host)return;const exerciseOptions=fallbackExercises.map(x=>`<option value="${esc(x.name)}">${esc(x.name)} (${esc(x.group)})</option>`).join('');addModal(create?'Trainingsplan erstellen':'Trainingsplan bearbeiten',`<div class="field"><label>Name</label><input class="input" id="editor-plan-name" value="${esc(working.name)}"></div><div class="field"><label>Wochentag (optional)</label><select class="select" id="editor-plan-day">${[['','Kein fester Tag'],[1,'Montag'],[2,'Dienstag'],[3,'Mittwoch'],[4,'Donnerstag'],[5,'Freitag'],[6,'Samstag']].map(([day,name])=>`<option value="${day}" ${working.day===day?'selected':''}>${name}</option>`).join('')}</select></div><div class="separator"></div><div class="side-head">Übungen · ${working.exercises.length}</div><div class="exercise-editor">${working.exercises.map((e,i)=>`<div class="editor-row"><div><div class="editor-row-title">${i+1}. ${esc(e.name)}</div><div class="editor-row-meta">${e.sets} Sätze · ${esc(e.reps)} Wdh. · ${e.rest} Sek. Pause</div></div>${btn(ico('edit'),`tmp-edit|${i}`,'button small square ghost','aria-label="Übung bearbeiten"')}${btn(ico('x'),`tmp-remove|${i}`,'button small square ghost','aria-label="Übung entfernen"')}</div>`).join('')||'<div class="hint">Füge eine Übung hinzu.</div>'}</div><div class="field"><label>Übung aus Liste hinzufügen</label><select id="editor-ex-select" class="select"><option value="">Wähle eine Übung …</option>${exerciseOptions}</select></div><div class="field"><label>Oder eigene Übung</label><input class="input" id="editor-ex-custom" placeholder="z. B. Kurzhantelrudern"></div>${btn(`${ico('plus')} Übung hinzufügen`,'tmp-add','button secondary full')}<div class="separator"></div>${btn('Trainingsplan speichern','tmp-save','button primary full')}${!create?btn(`${ico('trash')} Plan löschen`,'tmp-delete','button danger full'):''}`);};
    let editIndex=null;
    const getInputs=()=>{working.name=document.getElementById('editor-plan-name')?.value.trim()||'Mein Trainingsplan';working.day=num(document.getElementById('editor-plan-day')?.value,0)||null;};
    const listener=ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const act=el.dataset.action;if(!act.startsWith('tmp-'))return;ev.stopPropagation();if(act==='tmp-add'){getInputs();const picked=document.getElementById('editor-ex-custom').value.trim()||document.getElementById('editor-ex-select').value;if(!picked){toast('Wähle zuerst eine Übung.');return;}working.exercises.push(ex(picked,2,'8–12'));draw();}if(act==='tmp-remove'){getInputs();working.exercises.splice(Number(act.split('|')[1]),1);draw();}if(act==='tmp-edit'){getInputs();editIndex=Number(act.split('|')[1]);const e=working.exercises[editIndex];addModal('Übung anpassen',`<div class="field"><label>Übung</label><input class="input" id="tmp-name" value="${esc(e.name)}"></div><div class="editor-fields"><div class="field"><label>Sätze</label><input class="input" id="tmp-sets" type="number" min="1" max="12" value="${e.sets}"></div><div class="field"><label>Wdh.-Ziel</label><input class="input" id="tmp-reps" value="${esc(e.reps)}"></div><div class="field"><label>Pause (Sek.)</label><input class="input" type="number" id="tmp-rest" min="15" max="600" step="15" value="${e.rest}"></div></div><div class="quick-actions">${btn('Nach oben','tmp-up','button small ghost',editIndex===0?'disabled':'')}${btn('Nach unten','tmp-down','button small ghost',editIndex===working.exercises.length-1?'disabled':'')}</div>${btn('Übernehmen','tmp-update-ex','button primary full')}`);}
      if(act==='tmp-up'||act==='tmp-down'){const to=editIndex+(act==='tmp-up'?-1:1);if(to<0||to>=working.exercises.length)return;[working.exercises[to],working.exercises[editIndex]]=[working.exercises[editIndex],working.exercises[to]];editIndex=to;draw();}
      if(act==='tmp-update-ex'){const e=working.exercises[editIndex];e.name=document.getElementById('tmp-name').value.trim()||e.name;e.sets=clamp(Math.floor(num(document.getElementById('tmp-sets').value,2)),1,12);e.reps=document.getElementById('tmp-reps').value.trim()||'8–12';e.rest=clamp(Math.floor(num(document.getElementById('tmp-rest').value,120)),15,600);draw();}
      if(act==='tmp-save'){getInputs();if(working.exercises.length===0){toast('Füge mindestens eine Übung hinzu.');return;}working.short=working.day?weekdayName[working.day].slice(0,2).toUpperCase():'FREI';if(create){working.id=id();state.templates.push(working);}else{state.templates=state.templates.map(t=>t.id===working.id?working:t);}save();closeModal();document.removeEventListener('click',listener,true);render();toast('Trainingsplan gespeichert.');}
      if(act==='tmp-delete'){if(!confirm('Trainingsplan löschen? Bereits gespeicherte Trainingseinheiten bleiben erhalten.'))return;state.templates=state.templates.filter(t=>t.id!==working.id);save();closeModal();document.removeEventListener('click',listener,true);render();toast('Plan gelöscht.');}
    };
    document.addEventListener('click',listener,true);templateClickHandler=listener;draw();
  }
  function activeExerciseModal(idx){const e=state.active.exercises[idx];addModal('Übung im aktuellen Training ändern',`<div class="helper">Nur für dieses Training. Dein gespeicherter Trainingsplan bleibt unverändert.</div><div class="field"><label>Übungsname</label><input class="input" id="active-ex-name" value="${esc(e.name)}"></div><div class="field"><label>Wiederholungsziel</label><input class="input" id="active-ex-reps" value="${esc(e.reps)}"></div><div class="field"><label>Pausenzeit (Sek.)</label><input class="input" id="active-ex-rest" type="number" min="15" max="600" step="15" value="${e.rest}"></div>${btn('Änderung übernehmen',`update-active-exercise|${idx}`,'button primary full')}`);}
  function addActiveExerciseModal(){addModal('Übung hinzufügen',`<div class="field"><label>Übung auswählen</label><select class="select" id="addactive-pick"><option value="">Wähle …</option>${fallbackExercises.map(x=>`<option value="${esc(x.name)}">${esc(x.name)} (${esc(x.group)})</option>`).join('')}</select></div><div class="field"><label>Oder eigene Übung</label><input class="input" id="addactive-custom" placeholder="Eigene Übung"></div>${btn(`${ico('plus')} Zu heutigem Training hinzufügen`,'confirm-add-active','button primary full')}`);}
  const download = (content,filename,mime) => {const blob=new Blob([content],{type:mime});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},900);};
  function backup(){download(JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),`hunter-backup-${today()}.json`,'application/json');toast('JSON-Backup erstellt.');}
  function csvEscape(value){let s=String(value??'');if(/^[=+@\-]/.test(s))s=`'${s}`;return `"${s.replaceAll('"','""')}"`;}
  function exportCSV(){const rows=[['Datum','Training','Übung','Satz','Gewicht (kg)','Wiederholungen','RIR','Quelle','Dauer (Min.)','Trainings-ID']];for(const w of state.workouts){for(const e of w.exercises){e.sets.filter(s=>s.done).forEach((s,i)=>rows.push([w.date,w.name,e.name,i+1,s.kg,s.reps,s.rir??'',w.source||'Hunter-System',w.duration||'',w.id]));}}download('\ufeff'+rows.map(row=>row.map(csvEscape).join(';')).join('\r\n'),`hunter-training-${today()}.csv`,'text/csv;charset=utf-8');toast('Trainingsdaten als CSV exportiert.');}
  async function importJSON(file){if(!file)return;let incoming;try{incoming=JSON.parse(await file.text());if(incoming.version!==1||!Array.isArray(incoming.templates)||!Array.isArray(incoming.workouts))throw new Error('Kein gültiges Hunter-System-Backup.');}catch(e){toast('Diese Datei ist kein gültiges Hunter-Backup.');return;}if(!confirm(`Backup importieren? Deine aktuellen Daten (${state.workouts.length} Trainings) werden überschrieben. Vorher am besten ein eigenes Backup exportieren.`))return;
    const oldSettings=state.settings;state=incoming;state.settings={...createDefaults().settings,...state.settings,oauthClientId:oldSettings.oauthClientId,spreadsheetId:oldSettings.spreadsheetId};state.quests ||= {};state.xp ||= {workoutIds:[]};state.sync ||= {lastPush:null};if(!save())return;selectedHistory=null;tab='home';render();toast(`Backup importiert: ${state.workouts.length} Trainings.`);
  }
  // Google OAuth via browser-side Google Identity Services. No app secret or Google password is collected.
  async function initGoogleSdk(){if(window.google?.accounts?.oauth2)return;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=()=>reject(new Error('Google-Anmeldung konnte nicht geladen werden.'));document.head.append(script);});}
  async function googleConnect(){const clientId=state.settings.oauthClientId;if(!clientId){toast('Trage zuerst deine OAuth-Client-ID ein und speichere sie.');return;}if(!window.isSecureContext){toast('Für Google-Anmeldung ist HTTPS erforderlich.');return;}try{await initGoogleSdk();const client=window.google.accounts.oauth2.initTokenClient({client_id:clientId,scope:'https://www.googleapis.com/auth/spreadsheets',callback:res=>{if(res.error){toast('Google-Anmeldung: '+res.error);return;}token=res.access_token;toast('Google Sheets verbunden.');render();}});client.requestAccessToken({prompt:'consent'});}catch(e){toast(e.message);}}
  async function sheetApi(path,{method='GET',body}={}){if(!token)throw new Error('Bitte zuerst Google verbinden.');const res=await fetch(`https://sheets.googleapis.com/v4/spreadsheets${path}`,{method,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let json;try{json=await res.json()}catch{json={}}if(!res.ok){if(res.status===401){token=null;}throw new Error(json.error?.message||`Google API: ${res.status}`);}return json;}
  async function createSheet(){if(!token){toast('Bitte Google zuerst verbinden.');return;}try{const book=await sheetApi('',{method:'POST',body:{properties:{title:'Hunter System – Gym Tracker'},sheets:['Training','Sessions','Quests','Plans','Backup'].map(title=>({properties:{title}}))}});state.settings.spreadsheetId=book.spreadsheetId;save();toast('Google-Tabelle erstellt. Speichere jetzt deine Daten.');render();await pushSheet();}catch(e){toast(`Tabelle konnte nicht erstellt werden: ${e.message}`);}}
  async function ensureSheets(spreadsheetId){const book=await sheetApi(`/${encodeURIComponent(spreadsheetId)}?fields=sheets.properties`);const names=new Set((book.sheets||[]).map(s=>s.properties.title));const missing=['Training','Sessions','Quests','Plans','Backup'].filter(s=>!names.has(s));if(missing.length)await sheetApi(`/${encodeURIComponent(spreadsheetId)}:batchUpdate`,{method:'POST',body:{requests:missing.map(title=>({addSheet:{properties:{title}}}))}});}
  function sheetsRows(){const train=[['Datum','Training','Übung','Satz','Gewicht_kg','Wiederholungen','RIR','Quelle','SessionID']];const sessions=[['SessionID','Datum','Trainingsname','Dauer_min','Quelle','Notizen']];const quest=[['Datum','Quest','Kategorie','Erledigt','XP']];const plans=[['Plan','Wochentag','Übung','Reihenfolge','Sätze','Wdh_Ziel','Pause_sek']];for(const w of state.workouts){sessions.push([w.id,w.date,w.name,w.duration||'',w.source||'Hunter-System',w.notes||'']);for(const e of w.exercises){e.sets.filter(s=>s.done).forEach((s,i)=>train.push([w.date,w.name,e.name,i+1,num(s.kg),num(s.reps),s.rir??'',w.source||'Hunter-System',w.id]));}}for(const [date,q] of Object.entries(state.quests)){for(const v of q.items||[])quest.push([date,v.name,v.type,q.completed?.[v.id]?'Ja':'Nein',q.completed?.[v.id]?v.xp:0]);}for(const p of state.templates){p.exercises.forEach((e,i)=>plans.push([p.name,weekdayName[p.day]||'Kein Tag',e.name,i+1,e.sets,e.reps,e.rest]));}return {Training:train,Sessions:sessions,Quests:quest,Plans:plans};}
  async function pushSheet(){if(syncInProgress)return;if(!token){toast('Bitte zuerst Google verbinden.');return;}const sheetId=state.settings.spreadsheetId;if(!sheetId){toast('Erstelle zuerst eine Google-Tabelle.');return;}syncInProgress=true;try{await ensureSheets(sheetId);const data=sheetsRows();const json=JSON.stringify(state);const chunks=json.match(/[\s\S]{1,12000}/g)||[''];data.Backup=[['HUNTER BACKUP CHUNKS','Nur über Hunter-System-App wiederherstellen'],...chunks.map((chunk,i)=>[String(i+1),chunk])];const ranges=Object.keys(data).map(n=>`'${n}'!A1:Z`);await sheetApi(`/${encodeURIComponent(sheetId)}/values:batchClear`,{method:'POST',body:{ranges}});const body={valueInputOption:'RAW',data:Object.entries(data).map(([name,rows])=>({range:`'${name}'!A1`,values:rows}))};await sheetApi(`/${encodeURIComponent(sheetId)}/values:batchUpdate`,{method:'POST',body});state.sync.lastPush=new Date().toISOString();save();render();toast('Google Sheets: alle Daten synchronisiert.');}catch(e){toast(`Sync fehlgeschlagen: ${e.message}`);console.error(e);}finally{syncInProgress=false;}}
  async function pullSheet(){if(!token){toast('Bitte Google zuerst verbinden.');return;}const sheetId=state.settings.spreadsheetId;if(!sheetId){toast('Keine Google-Tabelle eingetragen.');return;}if(!confirm('Daten aus Google Sheets laden? Das ersetzt deine lokalen Trainings und Quests. Exportiere vorher ein Backup.'))return;try{const data=await sheetApi(`/${encodeURIComponent(sheetId)}/values/${encodeURIComponent("'Backup'!A2:B10000")}`);const chunks=(data.values||[]).map(x=>x[1]).filter(Boolean);if(!chunks.length)throw new Error('In Backup sind keine Daten vorhanden.');const incoming=JSON.parse(chunks.join(''));if(incoming.version!==1||!Array.isArray(incoming.workouts)||!Array.isArray(incoming.templates))throw new Error('Kein gültiges Hunter-System-Backup.');const previous=state.settings;state=incoming;state.settings={...createDefaults().settings,...state.settings,oauthClientId:previous.oauthClientId,spreadsheetId:sheetId};state.sync ||= {lastPush:null};save();tab='home';render();toast('Daten aus Google Sheets geladen.');}catch(e){toast(`Laden fehlgeschlagen: ${e.message}`);}}
  function maybeAutoSync(){if(state.settings.autoSync && token && state.settings.spreadsheetId)pushSheet();}
  function ping(){try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const c=new A();const o=c.createOscillator();const g=c.createGain();o.type='sine';o.frequency.value=740;g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.18,c.currentTime+.02);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.25);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+.26);o.onended=()=>c.close();}catch{}}
  function handleAction(action,el){
    if(action==='close-modal'){closeModal();return;}
    if(action.startsWith('tmp-'))return;
    if(action==='go-training'){tab='training';render();return;}
    if(action==='go-quests'){tab='quests';render();return;}
    if(action==='go-progress'){tab='progress';render();return;}
    if(action==='go-settings'){tab='settings';render();return;}
    if(action.startsWith('start-workout|')){beginWorkout(action.split('|')[1]);return;}
    if(action==='finish-workout'){finishWorkout();return;}
    if(action==='discard-workout'){if(confirm('Aktives Training verwerfen? Nicht abgeschlossene Daten gehen verloren.')){state.active=null;save();render();}return;}
    if(action==='new-template'){templateModal(null);return;}
    if(action.startsWith('edit-template|')){templateModal(action.split('|')[1]);return;}
    if(action==='quest-toggle'){const d=questDay();const k=el.dataset.id;d.completed[k]=!d.completed[k];save();render();toast(d.completed[k]?'Quest erfüllt! XP erhalten.':'Quest wieder geöffnet.');return;}
    if(action==='reroll-quest'){const d=questDay();const pos=d.items.findIndex(q=>q.id==='movement');if(pos<0)return;const options=state.settings.questMode==='normal'?[['10 Liegestütze','Bei guter Tagesform; Alternative: auf den Knien.'],['15 freie Kniebeugen','Sauber und ohne Tempozwang.'],['5 Minuten Mobility','Sanft bewegen.'],['10 Minuten spazieren','Entspanntes Tempo.']]:[['5 Minuten Mobility','Sanft bewegen.'],['10 Minuten spazieren','Entspanntes Tempo.'],['3 Minuten dehnen','Entspannt bewegen.'],['Kurze Bewegungspause','5 Minuten leicht bewegen.']];const current=d.items[pos].name;const next=options[(options.findIndex(x=>x[0]===current)+1+options.length)%options.length];d.items[pos]={...d.items[pos],name:next[0],detail:next[1]};delete d.completed.movement;save();render();toast('Bewegungsquest ausgetauscht.');return;}
    if(action==='complete-set'){const ei=num(el.dataset.ex),si=num(el.dataset.set);const e=state.active?.exercises[ei];const s=e?.sets[si];if(!s)return;if(!s.done && num(s.reps)<=0){toast('Trage zuerst die Wiederholungen ein.');return;}s.done=!s.done;if(s.done){state.active.restTimer={end:Date.now()+e.rest*1000};elapsedRest=false;}else{state.active.restTimer=null;}save();render();return;}
    if(action==='rest-skip'){state.active.restTimer=null;elapsedRest=false;save();render();return;}
    if(action==='rest-plus'||action==='rest-minus'){if(!activeTimer())return;state.active.restTimer.end+=action==='rest-plus'?15000:-15000;elapsedRest=state.active.restTimer.end<=Date.now();save();render();return;}
    if(action.startsWith('add-active-set|')){const i=num(action.split('|')[1]);const e=state.active.exercises[i];const l=e.sets.at(-1);e.sets.push({id:id(),kg:l?.kg||0,reps:l?.reps||0,rir:null,done:false});save();render();return;}
    if(action.startsWith('remove-active-set|')){const i=num(action.split('|')[1]);const e=state.active.exercises[i];if(e.sets.length>1){e.sets.pop();save();render();}return;}
    if(action.startsWith('edit-active-exercise|')){activeExerciseModal(num(action.split('|')[1]));return;}
    if(action.startsWith('update-active-exercise|')){const e=state.active.exercises[num(action.split('|')[1])];e.name=document.getElementById('active-ex-name').value.trim()||e.name;e.reps=document.getElementById('active-ex-reps').value.trim()||e.reps;e.rest=clamp(Math.round(num(document.getElementById('active-ex-rest').value,120)),15,600);save();closeModal();render();return;}
    if(action.startsWith('remove-active-exercise|')){const idx=num(action.split('|')[1]);if(!confirm('Übung nur aus dem heutigen Training entfernen?'))return;state.active.exercises.splice(idx,1);save();render();return;}
    if(action==='add-active-exercise'){addActiveExerciseModal();return;}
    if(action==='confirm-add-active'){const n=document.getElementById('addactive-custom').value.trim()||document.getElementById('addactive-pick').value;if(!n){toast('Bitte eine Übung auswählen.');return;}state.active.exercises.push(buildActiveExercise(ex(n)));save();closeModal();render();return;}
    if(action.startsWith('view-history|')){selectedHistory=action.split('|')[1];render();return;}
    if(action==='close-history'){selectedHistory=null;render();return;}
    if(action.startsWith('delete-history|')){const wid=action.split('|')[1];if(!confirm('Diesen Trainingseintrag endgültig löschen?'))return;state.workouts=state.workouts.filter(w=>w.id!==wid);selectedHistory=null;save();render();return;}
    if(action==='export-json'){backup();return;}
    if(action==='export-csv'){exportCSV();return;}
    if(action==='import-json'){document.getElementById('file-import')?.click();return;}
    if(action==='save-settings'){state.settings.nickname=document.getElementById('settings-nickname').value.trim()||'Hunter';state.settings.restDefault=clamp(Math.round(num(document.getElementById('settings-rest').value,120)),30,600);state.settings.questMode=document.getElementById('settings-quest').value;save();render();toast('Einstellungen gespeichert.');return;}
    if(action==='save-google-settings'){state.settings.oauthClientId=document.getElementById('settings-clientid').value.trim();state.settings.spreadsheetId=document.getElementById('settings-sheetid').value.trim();state.settings.autoSync=!!document.getElementById('settings-autosync')?.checked;save();render();toast('Google-Einstellungen gespeichert.');return;}
    if(action==='google-connect'){googleConnect();return;}
    if(action==='google-create'){createSheet();return;}
    if(action==='google-push'){pushSheet();return;}
    if(action==='google-pull'){pullSheet();return;}
  }
  document.addEventListener('click',e=>{const tabNode=e.target.closest('[data-tab]');if(tabNode){tab=tabNode.dataset.tab;render();window.scrollTo({top:0,behavior:'instant'});return;}const el=e.target.closest('[data-action]');if(el)handleAction(el.dataset.action,el);if(e.target?.id==='modal-backdrop')closeModal();});
  document.addEventListener('change',e=>{const t=e.target;if(t.id==='progress-exercise'){selectedProgress=t.value;render();return;}if(t.id==='file-import'){importJSON(t.files?.[0]);t.value='';return;}if(t.dataset.setInput && state.active){const exIdx=num(t.dataset.ex),sIdx=num(t.dataset.set);const s=state.active.exercises[exIdx]?.sets[sIdx];if(!s)return;const field=t.dataset.setInput;if(field==='rir')s.rir=t.value===''?null:clamp(Math.floor(num(t.value)),0,5);else s[field]=field==='reps'?clamp(Math.floor(num(t.value)),0,500):clamp(num(t.value),0,1000);save();}});
  document.addEventListener('input',e=>{if(e.target?.id==='active-notes'&&state.active){state.active.notes=e.target.value;save();}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  elapsedRest=remain()===0;
  setInterval(()=>{if(!state.active)return;const elapsed=document.getElementById('active-elapsed');if(elapsed)elapsed.textContent=hhmm(Math.floor((Date.now()-state.active.startedAt)/1000));const node=document.getElementById('timer-value');const t=activeTimer();if(!node||!t)return;const left=remain();node.textContent=hhmm(left);if(left===0&&!elapsedRest){elapsedRest=true;const wrapper=document.getElementById('rest-timer');wrapper?.classList.add('finished');if(document.visibilityState==='visible'){ping();toast('Pause vorbei – bereit für den nächsten Satz!');}}},500);
  if('serviceWorker' in navigator && location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('Service Worker:',e)));
  render();
})();
